schema:
CREATE TABLE IF NOT EXISTS subscriptions (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, name VARCHAR(120) NOT NULL,
 amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, period VARCHAR(10) NOT NULL,
 next_due DATE NOT NULL, anchor_day INTEGER NOT NULL, remind_days INTEGER NOT NULL,
 active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS notifications (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, message VARCHAR(500) NOT NULL,
 dedup_key VARCHAR(160) NOT NULL UNIQUE, created_on DATE NOT NULL, is_read INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS payments (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, subscription_id INTEGER NOT NULL, due_on DATE NOT NULL,
 paid_on DATE NOT NULL, amount_minor BIGINT NOT NULL, UNIQUE(subscription_id,due_on),
 FOREIGN KEY(subscription_id) REFERENCES subscriptions(id)
);
